<?php

declare(strict_types=1);

namespace SugarCraft\Code\Tests\Protocol;

use PHPUnit\Framework\TestCase;
use SugarCraft\Code\Protocol\WebStrings;

/**
 * C-TUI-6.f: both generated mirrors of the chrome catalogue are pinned to
 * the language file that is their source.
 *
 *  - docs/protocol/web-strings.en.json — regenerated by
 *    scripts/gen-web-strings.php --write, rendered through the same
 *    WebStrings::englishBundleJson() derivation the script runs (the shape
 *    ProtocolSchemaDriftTest enforces for the protocol trio);
 *  - candy-code-web/src-web/lib/strings.en.generated.ts — the browser-side
 *    baseline, regenerated by the web package's gen-web-strings.mjs from
 *    the JSON above. When the web package is not part of this checkout the
 *    sibling is honestly absent and its own CI leg guards it; its presence
 *    without a current mirror goes red here.
 */
final class WebStringsDriftTest extends TestCase
{
    public function testTheGeneratedJsonMatchesTheCatalogueDerivation(): void
    {
        WebStrings::resetForTesting();
        $path = \dirname(__DIR__, 2) . '/docs/protocol/web-strings.en.json';
        $committed = @file_get_contents($path);

        self::assertIsString($committed, 'docs/protocol/web-strings.en.json is generated and committed; run php scripts/gen-web-strings.php --write');
        self::assertSame(
            WebStrings::englishBundleJson(),
            $committed,
            'the committed web strings bundle is stale — run `php scripts/gen-web-strings.php --write` from candy-code/',
        );
    }

    public function testTheBrowserMirrorMatchesTheBundle(): void
    {
        $bundlePath = \dirname(__DIR__, 2) . '/docs/protocol/web-strings.en.json';
        $mirrorPath = \dirname(__DIR__, 3) . '/candy-code-web/src-web/lib/strings.en.generated.ts';

        if (!\is_dir(\dirname($mirrorPath))) {
            // Split-repo checkout of candy-code alone: the sibling package
            // (and its gen-web-strings.mjs leg) is not in this tree.
            self::assertDirectoryDoesNotExist(\dirname($mirrorPath));

            return;
        }

        self::assertFileExists($mirrorPath, 'the web package is present but carries no mirror — run npm run gen:strings in candy-code-web/');
        $ts = (string) file_get_contents($mirrorPath);
        /** @var array<string, string> $bundle */
        $bundle = (array) json_decode((string) file_get_contents($bundlePath), true);

        $mirror = [];
        self::assertMatchesRegularExpression(
            '/export const WEB_STRINGS_EN: Record<string, string> = \{/',
            $ts,
            'the mirror must carry the generated header the mjs writes',
        );
        foreach (explode("\n", $ts) as $line) {
            if (preg_match('/^ {4}"([^"]+)": "(.*)"(,)?$/', $line, $m) === 1) {
                $mirror[$m[1]] = stripcslashes($m[2]);
            }
        }

        self::assertSame(
            $bundle,
            $mirror,
            'candy-code-web/src-web/lib/strings.en.generated.ts is stale — run `npm run gen:strings` in candy-code-web/ and commit it',
        );
    }
}
